head.script:
scwin.onLoadComplete = function() {
    $w.executeSubmission("submission1");
};
scwin.submission1_submitdone = function(e) {
    // scwin.setGridViewGroupBy1();
    // scwin.setGridViewGroupBy2();
};
scwin.countFormatFunction = function(value) {
    return "총판매수량 : " + value + " 개 ";
};
scwin.sumFormatFunction = function(value) {
    return "총판매액 : " + value + " 원 ";
};
scwin.gridView1_ongroupby = function(options) {
    var sDate = new Date();
    // options.hideHeader = true;		// [true | false] 상단 숨김 여부 default:false.
    // options.hideFooter = true;		// [true | false] 하단 숨김 여부 default:false.
    options.closeGroup = false;
    // options.sortIndex = ["branch"];
    // options.sortOrder = ["1"];
    options.rowNumHeader = {
        colSpan: "6",
        inputType: "expression",
        expression: "toggle() + depthStr() + ' [ ' + count() + ' 건 ] '",
        align: "left"
    };
    options.rowNumFooter = {
        colSpan: "4"
    };
    options.groupbyFooter = [{
        inputType: "expression",
        expression: "SUM('sale_number')",
        displayFormatter: "scwin.countFormatFunction",
        align: "center"
    }, {
        inputType: "expression",
        expression: "SUM('sale_price')",
        displayFormatter: "scwin.sumFormatFunction",
        align: "center"
    }];
    gridView1.groupby(options);
    var eDate = new Date();
    //txt1.setValue("1. options.closeGroup = false;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;duration[" + (eDate - sDate) + "ms]"); //error occurred !
};
scwin.trigger1_onclick = function(e) {
    gridView1.setFixedRightColumn(3);
};
scwin.trigger2_onclick = function(e) {
    gridView1.setFixedRightColumn(2);
};
scwin.trigger3_onclick = function(e) {
    gridView1.setFixedRightColumn(1);
};
scwin.trigger4_onclick = function(e) {
    gridView1.setFixedRightColumn(0);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_column9', 'drag-n-drop', {
        dx: 0,
        dy: -50
    })
}
scwin.checkVal = function() {
    return typeof WebSquare.wUnit.getDomById("gridView1_scrollX_fixedRight") == "object";
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('body').css('width', '1200px')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "valBeforeScoll = WebSquare.wUnit.getJq('#gridView1_column5').css('width')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_scrollX_right').scrollLeft = 600");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "valAfterScoll = WebSquare.wUnit.getJq('#gridView1_column5').css('width')");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "valBeforeScoll != valAfterScoll", "true");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_scrollX_right').scrollLeft = 100");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    scwin.onLoadComplete();
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 09-Mar-2018
    window.valBeforeScoll;
	window.valAfterScoll;
    //end
}
